#
# Foxhound as a scenario manifest: the compiler's version of the hand-written example package
# modes/objectives/tests/fixtures/foxhound. test_scenarios.py compiles it and runs every YAML
# test of the objectives package that plays the hand-written one against the compiled package.
id: org.club.foxhound
version: 0.1.0
name: Foxhound
description: >-
  Red takes the bridge, which reveals the vault to red; both teams race for the intel
  (two players of a team scan their tags); red arms the bomb at site A and blue defends it.
lang: pt
teams: [red, blue]
params:
  vault_points: { type: int, min: 0, max: 1000, default: 100, label: "Points for the vault" }
i18n:
  pt:
    name: Foxhound
    description: >-
      A equipa red toma a ponte, o que lhe revela o cofre; as duas equipas disputam as
      informações (duas pessoas de uma equipa leem as suas etiquetas); a red arma a bomba no
      local A e a blue defende-o.
    params:
      vault_points: Pontos do cofre

nodes:
  alpha: { role: objective }
  bravo: { role: objective }
  charlie: { role: objective }
  site: { role: bomb_site }

objectives:
  - id: bridge
    name: Bridge
    i18n: { pt: { name: Ponte } }
    type: capture_and_hold
    target: alpha
    assignee: { team: red }
    params: { hold_ms: 3000 }
    effect: { points: 50 }

  - id: intel
    name: Intel
    description: Two players of one team scan their own tags here.
    i18n: { pt: { name: Informações, description: Duas pessoas da mesma equipa leem aqui as suas etiquetas. } }
    type: scan_tags
    target: bravo
    params: { tag_count: 2 }
    effect: { points: 20 }

  - id: vault
    name: Vault
    i18n: { pt: { name: Cofre } }
    type: enter_code
    target: charlie
    assignee: { team: red }
    params: { code: "4711" }
    visibility: hidden
    depends_on: [bridge]
    effect: { points: { param: vault_points } }

  - id: site_a
    name: Site A
    i18n: { pt: { name: Local A } }
    type: destroy
    target: site
    assignee: { team: red }
    params: { hold_ms: 5000, fuse_s: 60 }
    visibility: public   # blue defends it: both teams see it
    effect: { points: 30 }

id: org.club.every-type
version: 2.0.1
name: Every type
description: |
  A description on two lines; the first runs on and on, well past the hundred columns of mode.yaml, so that it folds.
  The second has "quotes", 'apostrophes', a colon: here, and a # hash.
author: The GM's team
lang: en
teams: [red, blue, green]
squads: 3
params:
  bonus: { type: int, min: 0, max: 500, default: 25, label: "Bonus points", gm_only: true }
  extra: { type: int, default: 0 }
  plain: { type: int, min: 5, max: 5, default: 5, label: null }
i18n:
  pt:
    name: Todos os tipos
    description: Uma descrição em português, com acentuação e cedilhas.
    params: { bonus: Pontos extra, extra: Mais }
nodes:
  alpha: { role: objective, level: 2 }
  bravo: { role: objective, level: 0 }
  charlie: { role: objective, level: null }
  delta: { role: objective }
  site: { role: bomb_site }
  vip: { player: true, role: vip }
  courier: { player: true }
objectives:
  - id: hill
    type: capture_and_hold
    name: Hill
    description: Hold it.
    i18n: { pt: { name: Colina, description: Segura-a. } }
    target: alpha
    assignee: { team: red, squad: 2 }
    params: { hold_ms: 3000, duration_s: 120 }
    time_window: { start_min: 5, end_min: 60 }
    effect: { points: { param: bonus }, win: false }
  - id: vault
    type: enter_code
    name: Vault
    target: bravo
    assignee: { team: blue }
    params: { code: "0815" }
    visibility: hidden
    depends_on: [hill]
    effect: { points: 100, reveal: [intel] }
  - id: intel
    type: scan_tags
    name: Intel
    target: charlie
    params: { tag_count: 3, any: true }
    visibility: hidden
    effect: { points: 0 }
  - id: rescue
    type: escort
    name: Rescue
    target: vip
    assignee: { team: red, squad: 1 }
    visibility: squad
    params:
      destination: { lat: 38, lon: -9.1393, radius_m: 25 }
      max_acc_m: 40
    effect: { points: 75, reveal: [extract] }
  - id: extract
    type: escort
    name: Extract
    target: vip
    assignee: { team: red }
    visibility: hidden
    params:
      destination: { points: [[38.7, -9.1], [38.7001, -9.1], [38.7001, -9.0999], [38, -9]] }
  - id: courier_run
    type: escort
    name: Courier
    target: courier
    params: { destination: { lat: -45.5, lon: 179.99999, radius_m: 12.5 } }
  - id: sabotage
    type: destroy
    name: Bomb
    target: site
    params: { hold_ms: 500, defuse_ms: 700, fuse_s: 60 }
    depends_on: [vault, intel]
    effect: { points: 30, win: true }
  - id: hq
    type: defend
    name: HQ
    target: delta
    assignee: { team: blue }
    visibility: team
    params: { duration_s: 2700, hold_ms: 0 }
    effect: { points: 60 }
  - id: last_stand
    type: survive
    name: Last stand
    assignee: { team: green }
    params: { minimum_lives: 5 }
    time_window: { end_min: 90 }
    effect: { points: { param: extra } }

id: org.club.hostile-texts
version: "1.0"
name: 'Pon"te]] os.exit(1) --[[ \'
description: "Tab\there, escape \e, bell \a, NUL \0, NEL \N, LS \L, PS \P, nbsp \_, BOM \uFEFF, RLO \u202E, private \uE000, astral \U0001F600, unassigned \U000E0080, end with spaces  "
author: "Ana Conceição 🚀 — 東京 עברית"
lang: pt
teams: ['r"ed', "it's", "yes", "null", "1", "~", "- x", "a: b"]
nodes:
  "al\"pha]]": { role: objective }
  "box #1": { role: objective }
  "? q": { role: objective }
  "[x]": { role: objective }
  "&z *w !t": { role: objective }
  "@q `r %p": { role: objective }
  "Ponte São João": { role: objective }
  "null": { role: objective }
  "2026-10-23": { role: bomb_site }
objectives:
  - id: bridge
    name: 'Pon"te]] os.exit(1) --[[ \'
    description: |
      line one ]] --[[
        indented line two, with trailing spaces
      line three
    type: capture_and_hold
    target: 'al"pha]]'
    assignee: { team: 'r"ed' }
    effect: { points: 7 }
  - id: hash
    name: "a # not a comment: really"
    description: "  leading spaces, and a final newline\n"
    type: capture_and_hold
    target: "box #1"
    assignee: { team: "it's" }
  - id: query
    name: "?"
    description: "-"
    type: enter_code
    target: "? q"
    params: { code: "00000001" }
    assignee: { team: "yes" }
  - id: brackets
    name: "Café ﷺ ∑ ½ ⅷ € ✓ 𝔘 ⃝"
    description: "e\u0301 combining, ﬁ ligature, ǅ titlecase, ʰ modifier, 〇 ideograph"
    type: scan_tags
    target: "[x]"
    params: { tag_count: 100 }
    assignee: { team: "null" }
  - id: amp
    name: "x\u00a0nbsp \u3000 ideographic space"
    type: capture_and_hold
    target: "&z *w !t"
    assignee: { team: "1" }
  - id: at
    name: "\uE000 private and \U000E0080 unassigned"
    type: capture_and_hold
    target: "@q `r %p"
    assignee: { team: "~" }
  - id: ponte
    name: "true"
    i18n: { pt: { name: "1.5" } }
    type: capture_and_hold
    target: "Ponte São João"
    assignee: { team: "- x" }
  - id: nulls
    name: "null"
    i18n: { pt: { name: "'quoted'" } }
    type: capture_and_hold
    target: "null"
    assignee: { team: "a: b" }
  - id: datebox
    name: "2026-10-23"
    i18n: { pt: { name: '"double"' } }
    type: destroy
    target: "2026-10-23"

